-- «3 ставить»: отметка «Проверенный» на карточке оператора.
UPDATE partners
   SET is_verified = TRUE, updated_at = NOW()
 WHERE slug = 'laguna-expedition'
   AND is_verified IS DISTINCT FROM TRUE;

DO $$
DECLARE
  v_p   int;
  v_n   int;
  v_ver boolean;
BEGIN
  SELECT count(*) INTO v_p FROM partners WHERE slug = 'laguna-expedition';
  IF v_p <> 1 THEN
    RAISE WARNING '[1339] карточек laguna-expedition: % (нужна одна, её заводит 1323) — туры не заведены', v_p;
    RETURN;
  END IF;
  SELECT count(*) INTO v_n FROM operator_tours t
    JOIN partners p ON p.id::text = t.operator_id::text
   WHERE p.slug = 'laguna-expedition' AND t.slug LIKE 'lagexp-%' AND t.deleted_at IS NULL;
  IF v_n <> 34 THEN
    RAISE WARNING '[1339] у «Лагуны Экспедиции» % туров с сайта, ожидалось 34 (адрес тура занят другим оператором или тур удалён?)', v_n;
  END IF;
  SELECT is_verified INTO v_ver FROM partners WHERE slug = 'laguna-expedition';
  IF v_ver IS DISTINCT FROM TRUE THEN
    RAISE WARNING '[1339] отметка «Проверенный» у «Лагуны Экспедиции» не стоит';
  END IF;
END $$;
